'use client';

import { useRouter } from 'next/navigation';
import { useRef, useState, type FormEvent, type KeyboardEvent } from 'react';
import { AnalysisRequestError, requestAnalysis } from '@/lib/analyze-client';
import { saveAnalysisSession } from '@/lib/storage';
import type { AnalyzeRequest, Scenario } from '@/lib/types';

const INTEREST_OPTIONS = [
  '数据分析',
  '人工智能',
  '产品与用户',
  '内容创作',
  '项目管理',
  '自动化',
  '教育培训',
  '商业分析',
] as const;

const SCENARIO_OPTIONS: { value: Scenario; title: string; description: string }[] = [
  { value: 'slow', title: 'AI 变化较缓', description: '按 12 个月节奏规划，偏稳健。' },
  { value: 'fast', title: 'AI 变化较快', description: '按 6 个月节奏规划，优先补关键短板。' },
];

const MAX_SKILLS = 30;
const MAX_TASKS = 20;

type FormErrors = {
  currentRole?: string;
  dailyTasks?: string;
  existingSkills?: string;
  experienceYears?: string;
};

type SubmitError = {
  message: string;
  details: string[];
};

const inputClass =
  'w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 placeholder:text-slate-400 transition focus:border-slate-500 focus:outline-none focus:ring-2 focus:ring-slate-200';

export default function HomePage() {
  const router = useRouter();
  const formRef = useRef<HTMLFormElement>(null);
  const [currentRole, setCurrentRole] = useState('');
  const [tasks, setTasks] = useState<string[]>(['']);
  const [skills, setSkills] = useState<string[]>([]);
  const [skillInput, setSkillInput] = useState('');
  const [experienceYears, setExperienceYears] = useState('3');
  const [interests, setInterests] = useState<string[]>([]);
  const [weeklyStudyHours, setWeeklyStudyHours] = useState(8);
  const [scenario, setScenario] = useState<Scenario>('slow');
  const [errors, setErrors] = useState<FormErrors>({});
  const [submitError, setSubmitError] = useState<SubmitError | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const addTask = () => {
    if (tasks.length < MAX_TASKS) {
      setTasks((prev) => [...prev, '']);
    }
  };

  const updateTask = (index: number, value: string) => {
    setTasks((prev) => prev.map((task, i) => (i === index ? value : task)));
  };

  const removeTask = (index: number) => {
    setTasks((prev) => (prev.length === 1 ? [''] : prev.filter((_, i) => i !== index)));
  };

  const addSkill = () => {
    const value = skillInput.trim().replace(/[，,]+$/g, '').trim();
    if (!value) {
      setSkillInput('');
      return;
    }

    const exists = skills.some((skill) => skill.toLowerCase() === value.toLowerCase());
    if (!exists && skills.length < MAX_SKILLS) {
      setSkills((prev) => [...prev, value]);
    }
    setSkillInput('');
  };

  const handleSkillKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing) {
      return;
    }
    if (event.key === 'Enter' || event.key === ',' || event.key === '，') {
      event.preventDefault();
      addSkill();
    }
  };

  const toggleInterest = (interest: string) => {
    setInterests((prev) =>
      prev.includes(interest) ? prev.filter((item) => item !== interest) : [...prev, interest],
    );
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isSubmitting) {
      return;
    }

    const cleanedTasks = tasks.map((task) => task.trim()).filter(Boolean);
    const years = Number(experienceYears);
    const nextErrors: FormErrors = {};

    if (!currentRole.trim()) {
      nextErrors.currentRole = '请填写当前岗位。';
    }
    if (cleanedTasks.length === 0) {
      nextErrors.dailyTasks = '请至少填写一项日常任务。';
    }
    if (skills.length === 0) {
      nextErrors.existingSkills = '请至少添加一项已有技能。';
    }
    if (experienceYears.trim() === '' || !Number.isInteger(years) || years < 0 || years > 50) {
      nextErrors.experienceYears = '请输入 0–50 之间的整数。';
    }

    setErrors(nextErrors);
    setSubmitError(null);

    if (Object.keys(nextErrors).length > 0) {
      return;
    }

    const payload: AnalyzeRequest = {
      currentRole: currentRole.trim(),
      dailyTasks: cleanedTasks,
      existingSkills: skills,
      experienceYears: years,
      interests,
      weeklyStudyHours,
      scenario,
    };

    setIsSubmitting(true);

    try {
      const result = await requestAnalysis(payload);

      try {
        saveAnalysisSession({
          result,
          input: payload,
          savedAt: new Date().toISOString(),
        });
      } catch {
        setSubmitError({
          message: '结果已生成，但无法保存到当前会话，请重试。',
          details: [],
        });
        return;
      }

      router.push('/result');
    } catch (error) {
      if (error instanceof AnalysisRequestError) {
        setSubmitError({ message: error.message, details: error.details });
      } else {
        setSubmitError({ message: '分析失败，请稍后重试。', details: [] });
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <main className="mx-auto w-full max-w-3xl px-4 py-10 sm:py-14">
      <header className="mb-8">
        <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-[#0e7c57]">
          AI 技能转型导航
        </p>
        <h1 className="mt-2 text-2xl font-semibold tracking-tight sm:text-3xl">先描述你的工作现状</h1>
        <p className="mt-2 text-sm leading-6 text-slate-600">
          填写岗位、任务与学习投入，用于生成技能画像和转型建议。带 * 的为必填项。
        </p>
      </header>

      <form
        ref={formRef}
        noValidate
        aria-busy={isSubmitting}
        onSubmit={handleSubmit}
        className="space-y-7 glass p-5 sm:p-7"
      >
        <section className="space-y-2">
          <label htmlFor="currentRole" className="block text-sm font-medium text-slate-900">
            当前岗位 <span className="text-red-500">*</span>
          </label>
          <input
            id="currentRole"
            type="text"
            value={currentRole}
            onChange={(event) => setCurrentRole(event.target.value)}
            placeholder="例如：电商运营专员"
            aria-invalid={Boolean(errors.currentRole)}
            aria-describedby={errors.currentRole ? 'currentRole-error' : undefined}
            className={`${inputClass} ${errors.currentRole ? 'border-red-400 focus:border-red-500 focus:ring-red-100' : ''}`}
          />
          {errors.currentRole && (
            <p id="currentRole-error" className="text-xs text-red-600">
              {errors.currentRole}
            </p>
          )}
        </section>

        <section className="space-y-2">
          <div className="flex items-center justify-between gap-3">
            <label htmlFor="task-0" className="block text-sm font-medium text-slate-900">
              日常任务 <span className="text-red-500">*</span>
            </label>
            <button
              type="button"
              onClick={addTask}
              disabled={tasks.length >= MAX_TASKS}
              className="rounded-lg px-2 py-1 text-sm font-medium text-blue-700 transition hover:bg-blue-50 disabled:cursor-not-allowed disabled:text-slate-400 disabled:hover:bg-transparent"
            >
              + 添加任务
            </button>
          </div>
          <div className="space-y-2">
            {tasks.map((task, index) => (
              <div key={index} className="flex items-center gap-2">
                <input
                  id={`task-${index}`}
                  type="text"
                  value={task}
                  onChange={(event) => updateTask(index, event.target.value)}
                  placeholder={index === 0 ? '例如：整理每周销售报表' : '继续添加任务…'}
                  aria-label={`日常任务 ${index + 1}`}
                  className={inputClass}
                />
                <button
                  type="button"
                  onClick={() => removeTask(index)}
                  disabled={tasks.length === 1}
                  aria-label={`删除任务 ${index + 1}`}
                  className="shrink-0 rounded-lg px-2 py-1 text-sm text-slate-500 transition hover:bg-slate-100 hover:text-slate-900 disabled:cursor-not-allowed disabled:text-slate-300 disabled:hover:bg-transparent"
                >
                  删除
                </button>
              </div>
            ))}
          </div>
          {errors.dailyTasks ? (
            <p className="text-xs text-red-600">{errors.dailyTasks}</p>
          ) : (
            <p className="text-xs text-slate-500">可添加多项，最多 {MAX_TASKS} 项。</p>
          )}
        </section>

        <section className="space-y-2">
          <label htmlFor="skillInput" className="block text-sm font-medium text-slate-900">
            已有技能 <span className="text-red-500">*</span>
          </label>
          <div className="flex items-center gap-2">
            <input
              id="skillInput"
              type="text"
              value={skillInput}
              onChange={(event) => setSkillInput(event.target.value)}
              onKeyDown={handleSkillKeyDown}
              placeholder="输入技能后按 Enter，例如：Excel"
              aria-invalid={Boolean(errors.existingSkills)}
              aria-describedby={errors.existingSkills ? 'existingSkills-error' : undefined}
              className={`${inputClass} ${errors.existingSkills ? 'border-red-400 focus:border-red-500 focus:ring-red-100' : ''}`}
            />
            <button
              type="button"
              onClick={addSkill}
              className="shrink-0 rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm font-medium text-slate-700 transition hover:bg-slate-50"
            >
              添加
            </button>
          </div>
          {errors.existingSkills ? (
            <p id="existingSkills-error" className="text-xs text-red-600">
              {errors.existingSkills}
            </p>
          ) : (
            <p className="text-xs text-slate-500">
              按 Enter 或逗号添加，最多 {MAX_SKILLS} 项。
              {skills.length > 0 ? ` 已添加 ${skills.length} 项。` : ''}
            </p>
          )}
          {skills.length > 0 && (
            <ul className="flex flex-wrap gap-2 pt-1">
              {skills.map((skill) => (
                <li
                  key={skill}
                  className="inline-flex items-center gap-1 rounded-full bg-slate-100 py-1 pl-3 pr-2 text-sm text-slate-800"
                >
                  {skill}
                  <button
                    type="button"
                    onClick={() => setSkills((prev) => prev.filter((item) => item !== skill))}
                    aria-label={`移除技能 ${skill}`}
                    className="rounded-full px-1 text-slate-500 transition hover:bg-slate-200 hover:text-slate-900"
                  >
                    ×
                  </button>
                </li>
              ))}
            </ul>
          )}
        </section>

        <section className="space-y-2 sm:max-w-[14rem]">
          <label htmlFor="experienceYears" className="block text-sm font-medium text-slate-900">
            工作经验年数
          </label>
          <div className="flex items-center gap-2">
            <input
              id="experienceYears"
              type="number"
              min={0}
              max={50}
              step={1}
              inputMode="numeric"
              value={experienceYears}
              onChange={(event) => setExperienceYears(event.target.value)}
              aria-invalid={Boolean(errors.experienceYears)}
              aria-describedby={errors.experienceYears ? 'experienceYears-error' : undefined}
              className={`${inputClass} ${errors.experienceYears ? 'border-red-400 focus:border-red-500 focus:ring-red-100' : ''}`}
            />
            <span className="shrink-0 text-sm text-slate-500">年</span>
          </div>
          {errors.experienceYears && (
            <p id="experienceYears-error" className="text-xs text-red-600">
              {errors.experienceYears}
            </p>
          )}
        </section>

        <fieldset className="space-y-2">
          <legend className="block text-sm font-medium text-slate-900">兴趣</legend>
          <p className="text-xs text-slate-500">可多选，用于匹配相邻岗位。</p>
          <div className="flex flex-wrap gap-2 pt-1">
            {INTEREST_OPTIONS.map((interest) => {
              const selected = interests.includes(interest);
              return (
                <button
                  key={interest}
                  type="button"
                  aria-pressed={selected}
                  onClick={() => toggleInterest(interest)}
                  className={`rounded-full border px-3 py-1.5 text-sm transition ${
                    selected
                      ? 'border-slate-900 bg-slate-900 text-white'
                      : 'border-slate-300 bg-white text-slate-700 hover:border-slate-400'
                  }`}
                >
                  {interest}
                </button>
              );
            })}
          </div>
        </fieldset>

        <section className="space-y-2">
          <div className="flex items-center justify-between gap-3">
            <label htmlFor="weeklyStudyHours" className="text-sm font-medium text-slate-900">
              每周可学习时间
            </label>
            <span className="text-sm font-medium text-slate-700">{weeklyStudyHours} 小时 / 周</span>
          </div>
          <input
            id="weeklyStudyHours"
            type="range"
            min={1}
            max={40}
            step={1}
            value={weeklyStudyHours}
            onChange={(event) => setWeeklyStudyHours(Number(event.target.value))}
            className="w-full cursor-pointer accent-slate-900"
          />
          <div className="flex justify-between text-xs text-slate-500">
            <span>1 小时</span>
            <span>40 小时</span>
          </div>
        </section>

        <fieldset className="space-y-2">
          <legend className="block text-sm font-medium text-slate-900">情景选择</legend>
          <div className="grid gap-2 sm:grid-cols-2">
            {SCENARIO_OPTIONS.map((option) => {
              const selected = scenario === option.value;
              return (
                <label
                  key={option.value}
                  className={`flex cursor-pointer items-start gap-3 rounded-xl border p-4 transition ${
                    selected
                      ? 'border-slate-900 bg-slate-50 ring-1 ring-slate-900'
                      : 'border-slate-200 hover:border-slate-300'
                  }`}
                >
                  <input
                    type="radio"
                    name="scenario"
                    value={option.value}
                    checked={selected}
                    onChange={() => setScenario(option.value)}
                    className="mt-1 accent-slate-900"
                  />
                  <span>
                    <span className="block text-sm font-medium text-slate-900">{option.title}</span>
                    <span className="mt-0.5 block text-xs leading-5 text-slate-500">
                      {option.description}
                    </span>
                  </span>
                </label>
              );
            })}
          </div>
        </fieldset>

        <div className="border-t border-slate-200 pt-5">
          {isSubmitting && (
            <div
              role="status"
              aria-live="polite"
              className="mb-4 flex items-center gap-2 rounded-lg border border-[rgba(14,124,87,0.20)] bg-[rgba(14,124,87,0.07)] px-3 py-2.5 text-sm text-[#0e7c57]"
            >
              <span
                className="h-4 w-4 animate-spin rounded-full border-2 border-blue-200 border-t-blue-600"
                aria-hidden="true"
              />
              正在分析你的档案，请稍候…
            </div>
          )}
          {submitError && (
            <div role="alert" className="mb-4 rounded-lg border border-red-200 bg-red-50 p-3">
              <p className="text-sm font-medium text-red-700">{submitError.message}</p>
              {submitError.details.length > 0 && (
                <ul className="mt-1 list-disc space-y-0.5 pl-5 text-xs text-red-600">
                  {submitError.details.map((detail) => (
                    <li key={detail}>{detail}</li>
                  ))}
                </ul>
              )}
              <button
                type="button"
                onClick={() => formRef.current?.requestSubmit()}
                disabled={isSubmitting}
                className="mt-3 rounded-md border border-red-300 bg-white px-3 py-1.5 text-xs font-medium text-red-700 transition hover:bg-red-100 disabled:cursor-not-allowed disabled:opacity-60"
              >
                重试
              </button>
            </div>
          )}
          <button
            type="submit"
            disabled={isSubmitting}
            className="flex w-full items-center justify-center gap-2 rounded-xl bg-[#0e7c57] px-4 py-3 text-sm font-semibold text-white shadow-[0_10px_24px_rgba(14,124,87,0.22)] transition hover:bg-[#0b6a4a] focus:outline-none focus-visible:ring-2 focus-visible:ring-[#0e7c57] focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:bg-[#87a99a]"
          >
            {isSubmitting ? (
              <>
                <span
                  className="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white"
                  aria-hidden="true"
                />
                正在分析你的档案…
              </>
            ) : (
              '生成转型建议'
            )}
          </button>
          <p className="mt-3 text-center text-xs text-slate-500">
            提交后将调用分析接口，并跳转到结果页。
          </p>
        </div>
      </form>
    </main>
  );
}
